/*
  Run in pgAdmin Query Tool against the dd_gateway database before creating
  partners or credentials. Missing tables and indexes are created; existing
  tables are left in place.
*/

CREATE TABLE IF NOT EXISTS "RequestLogs" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_RequestLogs" PRIMARY KEY,
    "CreatedAt" timestamp with time zone NOT NULL,
    "RequestId" character varying(100) NOT NULL,
    "Path" character varying(2048) NOT NULL,
    "Method" character varying(20) NOT NULL,
    "RequestBody" text NOT NULL,
    "ResponseBody" text NOT NULL,
    "StatusCode" integer NOT NULL,
    "Duration" integer NOT NULL,
    "IpAddress" character varying(100) NOT NULL,
    "ErrorMessage" text NOT NULL,
    "StackTrace" text NOT NULL,
    "RequestHeader" text NOT NULL
);

CREATE INDEX IF NOT EXISTS "IX_RequestLogs_CreatedAt" ON "RequestLogs" ("CreatedAt");
CREATE INDEX IF NOT EXISTS "IX_RequestLogs_RequestId" ON "RequestLogs" ("RequestId");

CREATE TABLE IF NOT EXISTS "Partners" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_Partners" PRIMARY KEY,
    "Code" character varying(50) NOT NULL,
    "Name" character varying(200) NOT NULL,
    "CallbackUrl" character varying(2048),
    "Status" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_Partners_Code" ON "Partners" ("Code");

CREATE TABLE IF NOT EXISTS "PartnerCredentials" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY CONSTRAINT "PK_PartnerCredentials" PRIMARY KEY,
    "PartnerId" integer NOT NULL,
    "AccessKey" character varying(100) NOT NULL,
    "SecretKey" character varying(100),
    "SecretKeyHash" character varying(100) NOT NULL,
    "Scopes" character varying(1000) NOT NULL,
    "Status" integer NOT NULL,
    "ExpiresAt" timestamp with time zone,
    "LastUsedAt" timestamp with time zone,
    "RevokedAt" timestamp with time zone,
    "CreatedAt" timestamp with time zone NOT NULL,
    "UpdatedAt" timestamp with time zone NOT NULL,
    CONSTRAINT "FK_PartnerCredentials_Partners_PartnerId"
        FOREIGN KEY ("PartnerId") REFERENCES "Partners" ("Id") ON DELETE RESTRICT
);

CREATE UNIQUE INDEX IF NOT EXISTS "IX_PartnerCredentials_AccessKey"
    ON "PartnerCredentials" ("AccessKey");
CREATE INDEX IF NOT EXISTS "IX_PartnerCredentials_PartnerId"
    ON "PartnerCredentials" ("PartnerId");

CREATE TABLE IF NOT EXISTS "EkycSessions" (
    "SessionId" character varying(36) CONSTRAINT "PK_EkycSessions" PRIMARY KEY,
    "PartnerId" integer NOT NULL,
    "NabPartnerId" character varying(100) NOT NULL,
    "CallbackUrl" character varying(2048) NOT NULL,
    "IssuedAt" bigint NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL,
    "VerifiedAt" timestamp with time zone,
    "ResultHash" character varying(64),
    "Status" character varying(20),
    "Code" character varying(2),
    CONSTRAINT "FK_EkycSessions_Partners_PartnerId"
        FOREIGN KEY ("PartnerId") REFERENCES "Partners" ("Id") ON DELETE RESTRICT
);

CREATE INDEX IF NOT EXISTS "IX_EkycSessions_PartnerId_CreatedAt"
    ON "EkycSessions" ("PartnerId", "CreatedAt");
